probe.source:
import assert from 'node:assert/strict';
import {spawnSync} from 'node:child_process';
import {readFileSync, writeFileSync} from 'node:fs';
import {fileURLToPath} from 'node:url';
const path = name => fileURLToPath(new URL(name, import.meta.url));
const variant = process.argv[2];
const marker = 'function _M0FP210JingLan0v03stn19append__order__rule(';
const pattern = /_M0MPC15array5Array8containsGsE\(rule_ids, id\)/;
const header = `const stats = {checks:0, comparisons:0, ms:0};
function checkOrderId(ids, id) {
  const start = performance.now();
  stats.checks++;
  for (const current of ids) {
    stats.comparisons++;
    if (current === id) { stats.ms += performance.now() - start; return true; }
  }
  stats.ms += performance.now() - start;
  return false;
}
process.once('exit', () => console.error(JSON.stringify(stats)));\n`;
for (const driver of ['deepbench','lookupbench']) {
  const source = readFileSync(path(variant + '-' + driver + '.js'), 'utf8');
  const from = source.indexOf(marker);
  const to = source.indexOf('\nfunction ', from + marker.length);
  const body = source.slice(from, to);
  assert(from >= 0 && to > from && pattern.test(body));
  writeFileSync(path(variant + '-' + driver + '-probe.js'), header + source.slice(0, from) +
    body.replace(pattern, 'checkOrderId(rule_ids, id)') + source.slice(to));
}
const rows = ['tight-impossible', 'maintenance', 'max-model'].map(name => {
  const args = name === 'tight-impossible' ? ['deepbench'] : ['lookupbench', name];
  args[0] = path(variant + '-' + args[0] + '-probe.js');
  const probes = Array.from({length:3}, () => {
    const result = spawnSync(process.execPath, args, {encoding:'utf8',timeout:30000});
    assert.equal(result.status, 0, result.stderr);
    assert.equal(result.stdout.trim().split(/\r?\n/).length, 9);
    return JSON.parse(result.stderr);
  });
  return {name, probes};
});
writeFileSync(path(variant + '-probe.json'), JSON.stringify(rows, null, 2) + '\n');
console.log(JSON.stringify(rows));

